                CALC: begin
                    if (start_cnt) begin
                        if (cnt == 8) begin
                            // Division complete
                            start_cnt <= 0;
                            cnt <= 0;
                            // Restore signs if needed
                            if (sign_reg) begin
                                quotient <= remainder[7] ? -quotient : quotient;
                                remainder <= remainder[7] ? -remainder : remainder;
