    if (RST) begin
        Mins <= 6'd0;
    end else begin
        if (Mins == 6'd59 && Secs == 6'd59) begin
            Mins <= 6'd0;
        end else if (Secs == 6'd59) begin
            Mins <= Mins + 6'd1;
        end
    end
